    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address who) public payable {
        uint256 beforeBalance = c.balances(who); if (__ESBMC_reverted()) return;
        uint256 beforeReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (beforeBalance > beforeReserve));
    }
}

