pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address who) internal {
        uint256 beforeBalance;
        try c.balances(who) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeReserve = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (beforeBalance > beforeReserve));
    }

    function testFuzz_run(address who) public {
